 *   corresponding HTML entities. The caller is responsible for freeing the
 *   returned string. Returns NULL if memory allocation fails.
 */
char* html_escape(const char* input) {
    if (input == NULL) {
        return NULL;
    }

    // Calculate the length required for the escaped string
    size_t len = 0;
    const char* ptr = input;
    while (*ptr) {
        switch (*ptr) {
            case '&':  len += 5; break; // &amp;
            case '<':  len += 4; break; // &lt;
            case '>':  len += 4; break; // &gt;
            case '\"': len += 6; break; // &quot;
            case '\'': len += 6; break; // &#x27;
            default:   len += 1; break;
        }
        ptr++;
    }

    // Allocate memory for the escaped string
    char* escaped = malloc(len + 1); // +1 for null terminator
    if (escaped == NULL) {
        return NULL; // Allocation failed
    }

    // Populate the escaped string
    char* dest = escaped;
    ptr = input;
    while (*ptr) {
        switch (*ptr) {
            case '&':
                memcpy(dest, "&amp;", 5);
                dest += 5;
                break;
            case '<':
                memcpy(dest, "&lt;", 4);
                dest += 4;
                break;
            case '>':
                memcpy(dest, "&gt;", 4);
                dest += 4;
                break;
            case '\"':
                memcpy(dest, "&quot;", 6);
                dest += 6;
                break;
            case '\'':
                memcpy(dest, "&#x27;", 6);
                dest += 6;
                break;
            default:
                *dest = *ptr;
                dest += 1;
